package android.app;import android.content.*;public final class PendingIntent {public static final int FLAG_IMMUTABLE=1,FLAG_CANCEL_CURRENT=2;public static int created;public final Intent intent;public final int flags;public boolean cancelled;PendingIntent(Intent i,int f){intent=i;flags=f;}public static PendingIntent getBroadcast(Context c,int n,Intent i,int flags){created++;return new PendingIntent(i,flags);}public void cancel(){cancelled=true;}}
